import React, { useState } from "react";
import "./AdminDashboard.css";

export default function AdminDashboard({ reports, token, setMsg }) {
  const [ngos, setNgos] = useState(null);
  const [events, setEvents] = useState(null);
  const [eventStats, setEventStats] = useState(null);
  const [topStats, setTopStats] = useState(null);

  const API = process.env.REACT_APP_API || "http://localhost:4000";

  // Generic fetch handler
  const loadData = async (endpoint, setter, field, errMsg) => {
    if (!token) return setMsg("Login as admin first");
    try {
      const res = await fetch(`${API}${endpoint}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        // try to read json msg
        const text = await res.text().catch(() => null);
        throw new Error(text || errMsg);
      }
      const data = await res.json();
      setter(data[field] || []);
    } catch (e) {
      console.error(e);
      setMsg(e.message || errMsg);
    }
  };

  // Load Top Performers (real data from backend)
  const loadTopPerformers = async () => {
    if (!token) return setMsg("Login as admin first");
    try {
      const res = await fetch(`${API}/api/actions/top-performers`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) {
        const text = await res.text().catch(() => null);
        throw new Error(text || "Failed to load top performers");
      }
      const data = await res.json();
      setTopStats(data.top || null);
    } catch (e) {
      console.error(e);
      setMsg(e.message || "Failed to load top performers");
    }
  };

  // Delete NGO (unchanged logic)
  const deleteNgo = async (id) => {
    if (!token) return setMsg("Login as admin first");

    if (!window.confirm("Are you sure you want to remove this NGO?")) return;

    try {
      const res = await fetch(`${API}/api/actions/remove-ngo/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        const text = await res.text().catch(() => null);
        throw new Error(text || "Failed to delete NGO");
      }

      setMsg("NGO removed successfully");
      setNgos((prev) => prev.filter((n) => n.id !== id)); // update UI instantly
    } catch (e) {
      console.error(e);
      setMsg(e.message);
    }
  };

  return (
    <div className="admin-panel">

      {/* LEFT: Reports + Action Buttons + Lists (wider main container) */}
      <div className="left-col">
        <h3>Admin Reports</h3>

        <div className="cards-row">
          <div className="stat-card">
            <div className="stat-num">
              {reports?.donations
                ? reports.donations.reduce((s, d) => s + parseFloat(d.amount || 0), 0)
                : "-"}
            </div>
            <div className="stat-label">Total Donation Amount (₹)</div>
          </div>

          <div className="stat-card">
            <div className="stat-num">{reports?.volunteers?.length || 0}</div>
            <div className="stat-label">Total Volunteers</div>
          </div>

          <div className="stat-card">
            <div className="stat-num">{reports?.feedbacks?.length || 0}</div>
            <div className="stat-label">Feedbacks</div>
          </div>
        </div>

        {/* ACTION BUTTONS */}
        <div className="actions-row">
          <button
            onClick={() =>
              loadData("/api/actions/ngos", setNgos, "ngos", "Failed to load NGOs")
            }
            className="btn"
          >
            View Registered NGOs
          </button>

          <button
            onClick={() =>
              loadData(
                "/api/actions/registered-events",
                setEvents,
                "events",
                "Failed to load events"
              )
            }
            className="btn"
          >
            View Registered Events
          </button>

          <button
            onClick={() =>
              loadData(
                "/api/actions/event-stats",
                setEventStats,
                "events",
                "Failed to load event stats"
              )
            }
            className="btn"
          >
            View Event Stats
          </button>
        </div>

        {/* EVENT LIST */}
        {events && (
          <div className="section">
            <h4>Registered Events</h4>
            {events.length ? (
              events.map((e) => (
                <div key={e.id} className="list-item">
                  <div>
                    <strong>{e.title}</strong>
                    <div className="muted">{e.date}</div>
                  </div>
                </div>
              ))
            ) : (
              <p>No events registered.</p>
            )}
          </div>
        )}

        {/* EVENT STATS */}
        {eventStats && (
          <div className="section" style={{ maxWidth: 780 }}>
            <h4>Event Statistics</h4>
            {eventStats.length ? (
              eventStats.map((ev) => (
                <div key={ev.id} className="event-stat">
                  <img
                    src={ev.image_url || "https://via.placeholder.com/120x80"}
                    alt="ev"
                    className="ev-thumb"
                  />
                  <div className="ev-info">
                    <div className="ev-title">{ev.title}</div>
                    <div className="muted">
                      Volunteers: {ev.volunteers_count} — Donations: ₹{ev.donations_sum}
                    </div>
                  </div>
                </div>
              ))
            ) : (
              <p>No event statistics loaded.</p>
            )}
          </div>
        )}

        {/* NGO LIST */}
        {ngos && (
          <div className="section">
            <h4>Registered NGOs</h4>
            {ngos.length ? (
              ngos.map((n) => (
                <div key={n.id} className="list-item space-between">
                  <div>
                    <strong>{n.name}</strong>
                    <div className="muted">{n.email}</div>
                  </div>

                  <div style={{ display: "flex", gap: 8 }}>
                    <button
                      className="btn small"
                      onClick={() => {
                        // keep existing behavior if you had a view NGO action
                        // for now, attempt to open NGO profile in same app route
                        window.location.href = `/ngo/${n.id}`;
                      }}
                    >
                      View
                    </button>

                    <button
                      style={{ background: "#e53935" }}
                      className="btn small"
                      onClick={() => deleteNgo(n.id)}
                    >
                      Remove
                    </button>
                  </div>
                </div>
              ))
            ) : (
              <p>No NGOs registered.</p>
            )}
          </div>
        )}
      </div>

      {/* RIGHT: Top Performers box (separate, with its own button) */}
      <div className="right-col">
        <div className="top-box">
          <div className="top-header">
            <h3>Top Performers</h3>
            <button className="btn small" onClick={loadTopPerformers}>
              View Top Performers
            </button>
          </div>

          {topStats ? (
            <>
              <div className="top-row">
                <div className="mini-card">
                  <div className="mini-title">Most Volunteers — Today</div>
                  {topStats.todayMostVolunteers ? (
                    <>
                      <div className="mini-value">{topStats.todayMostVolunteers.title}</div>
                      <div className="muted">Volunteers: {topStats.todayMostVolunteers.count}</div>
                    </>
                  ) : (
                    <div className="muted">No data for today</div>
                  )}
                </div>

                <div className="mini-card">
                  <div className="mini-title">Most Donations — Today</div>
                  {topStats.todayMostDonations ? (
                    <>
                      <div className="mini-value">{topStats.todayMostDonations.title}</div>
                      <div className="muted">₹{topStats.todayMostDonations.amount}</div>
                    </>
                  ) : (
                    <div className="muted">No data for today</div>
                  )}
                </div>
              </div>

              <div className="top-row">
                <div className="mini-card">
                  <div className="mini-title">Most Volunteers — This Week</div>
                  {topStats.weekMostVolunteers ? (
                    <>
                      <div className="mini-value">{topStats.weekMostVolunteers.title}</div>
                      <div className="muted">Volunteers: {topStats.weekMostVolunteers.count}</div>
                    </>
                  ) : (
                    <div className="muted">No data for the week</div>
                  )}
                </div>

                <div className="mini-card">
                  <div className="mini-title">Most Donations — This Week</div>
                  {topStats.weekMostDonations ? (
                    <>
                      <div className="mini-value">{topStats.weekMostDonations.title}</div>
                      <div className="muted">₹{topStats.weekMostDonations.amount}</div>
                    </>
                  ) : (
                    <div className="muted">No data for the week</div>
                  )}
                </div>
              </div>
            </>
          ) : (
            <div className="muted" style={{ padding: "18px 0" }}>
              Click <strong>View Top Performers</strong> to load today's / this week's top events.
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
